TARGET_LOG_DIR = "/var/log/anaconda/"

def _writeKS_via_boss():
    boss_proxy = BOSS.get_proxy()
    ks_string = boss_proxy.GenerateKickstart()
    path = conf.target.system_root + "/root/anaconda-ks.cfg"

    with open_with_perm(path, "w", 0o600) as f:
        f.write("# Generated by Anaconda {}\n".format(util.get_anaconda_version_string()))
        f.write(ks_string)


class CopyLogsTask(InstallationTask):
    """Task to copy logs to target system."""
    def __init__(self, sysroot):
        """Create a new task.

        :param sysroot: a path to the root of installed system
        :type sysroot: str
        """
        super().__init__()
        self._sysroot = sysroot

    @property
    def name(self):
        return "Copy installation logs"

    def run(self):
        """Copy installation logs and other related files, and do necessary operations on them.

        - Copy logs of all kinds, incl. ks scripts, journal dump, and lorax pkg list
        - Copy input kickstart file
        - SELinux contexts are left as is (fixed by SetContextsTask)
        """
        self._copy_kickstart()
        self._copy_logs()

    def _copy_logs(self):
        """Copy installation logs to the target system"""
        if not conf.target.can_save_installation_logs:
            log.warning("Installation logs will not be saved to the installed system due to the "
                        "nosave option.")
            return

        log.info("Copying logs from the installation environment.")
        self._create_logs_directory()
        self._copy_tmp_logs()
        self._copy_lorax_packages()
        self._copy_pre_script_logs()
        self._copy_dnf_debugdata()
        self._copy_post_script_logs()
        self._dump_journal()

    def _create_logs_directory(self):
        """Create directory for Anaconda logs on the install target"""
        make_directories(join_paths(self._sysroot, TARGET_LOG_DIR))

    def _copy_tmp_logs(self):
        """Copy a number of log files from /tmp"""
        log_files_to_copy = [
            "anaconda.log",
            "syslog",
            "X.log",
            "program.log",
            "packaging.log",
            "storage.log",
            "ifcfg.log",
            "lvm.log",
            "dnf.librepo.log",
            "hawkey.log",
            "dbus.log",
        ]
        for logfile in log_files_to_copy:
            self._copy_file_to_sysroot(
                join_paths("/tmp/", logfile),
                join_paths(TARGET_LOG_DIR, logfile)
            )

    def _copy_lorax_packages(self):
        """Copy list of packages used for creating the installation media"""
        self._copy_file_to_sysroot(
            "/root/lorax-packages.log",
            join_paths(TARGET_LOG_DIR, "lorax-packages.log")
        )

    def _copy_pre_script_logs(self):
        """Copy logs from %pre scripts"""
        self._copy_tree_to_sysroot(
            "/tmp/pre-anaconda-logs",
            TARGET_LOG_DIR
        )

    def _copy_dnf_debugdata(self):
        """Copy DNF debug data"""
        self._copy_tree_to_sysroot(
            "/root/debugdata",
            join_paths(TARGET_LOG_DIR, "dnf_debugdata/")
        )

    def _copy_post_script_logs(self):
        """Copy logs from %post scripts"""
        for logfile in glob.glob("/tmp/ks-script*.log"):
            self._copy_file_to_sysroot(
                logfile,
                join_paths(TARGET_LOG_DIR, os.path.basename(logfile))
            )

    def _dump_journal(self):
        """Dump journal from the installation environment"""
        tempfile = "/tmp/journal.log"
        with open_with_perm(tempfile, "w", perm=0o600) as logfile:
            execWithRedirect("journalctl", ["-b"], stdout=logfile, log_output=False)
        self._copy_file_to_sysroot(tempfile, join_paths(TARGET_LOG_DIR, "journal.log"))

    def _copy_kickstart(self):
        """Copy input kickstart file"""
        if conf.target.can_copy_input_kickstart:
            log.info("Copying input kickstart file.")
            self._copy_file_to_sysroot(
                "/run/install/ks.cfg",
                "/root/original-ks.cfg"
            )
        else:
            log.warning("Input kickstart will not be saved to the installed system due to the "
                        "nosave option.")

    def _copy_file_to_sysroot(self, src, dest):
        """Copy a file, if it exists, and set its access bits.

        :param str src: path to source file
        :param str dest: path to destination file within sysroot
        """
        if os.path.exists(src):
            log.info("Copying file: %s -> %s", src, dest)
            full_dest_path = join_paths(self._sysroot, dest)
            shutil.copyfile(
                src,
                full_dest_path
            )
            os.chmod(full_dest_path, 0o0600)

    def _copy_tree_to_sysroot(self, src, dest):
        """Copy a directory tree, if it exists, and set its access bits.

        :param str src: path to source directory
        :param str dest: path to destination directory within sysroot
        """
        if os.path.exists(src):
            log.info("Copying directory tree: %s -> %s", src, dest)
            full_dest_path = join_paths(self._sysroot, dest)
            shutil.copytree(
                src,
                full_dest_path,
                dirs_exist_ok=True
            )
            os.chmod(full_dest_path, 0o0600)




BLAZE_SESSION_MAP = {
    "solarui": ("solarui", "wayland", "solarui.desktop"),
    "solarui_pure": ("solarui", "wayland", "solarui.desktop"),
    "solarui_gnome": ("solarui", "wayland", "solarui.desktop"),
    "gnome": ("gnome", "wayland", "gnome.desktop"),
    "niri": ("niri", "wayland", "niri.desktop"),
    "kde": ("plasma", "wayland", "plasma.desktop"),
    "cosmic": ("cosmic", "wayland", "cosmic.desktop"),
    "hyprland": ("hyprland", "wayland", "hyprland.desktop"),
    "cinnamon": ("cinnamon", "wayland", "cinnamon.desktop"),
    "xfce": ("xfce", "x11", "xfce.desktop"),
    "sway": ("sway", "wayland", "sway.desktop"),
}


class BlazeFinalizeInstallationTask(InstallationTask):
    """Task to finalize BlazeOS installation: remove liveuser, configure real user sessions, and apply bootloader."""

    def __init__(self, sysroot):
        super().__init__()
        self._sysroot = sysroot

    @property
    def name(self):
        return "Finalize Blaze SolarUI desktop and bootloader configuration"

    def run(self):
        log.info("=== Starting BlazeFinalizeInstallationTask on target sysroot: %s ===", self._sysroot)

        # 1. Determine user choice from /tmp/anaconda_desktop_choice
        desktop_choice = "solarui_pure"
        for choice_path in ["/tmp/anaconda_desktop_choice", "/run/anaconda/desktop_choice"]:
            if os.path.exists(choice_path):
                try:
                    with open(choice_path, "r", encoding="utf-8") as f:
                        val = f.read().strip()
                        if val:
                            desktop_choice = val
                            log.info("Read desktop choice: %s from %s", desktop_choice, choice_path)
                            break
                except Exception as e:
                    log.warning("Could not read %s: %s", choice_path, e)

        # 2. Determine bootloader choice from /tmp/anaconda_bootloader_choice
        bootloader_choice = "grub2"
        for choice_path in ["/tmp/anaconda_bootloader_choice", "/run/anaconda/bootloader_choice"]:
            if os.path.exists(choice_path):
                try:
                    with open(choice_path, "r", encoding="utf-8") as f:
                        val = f.read().strip()
                        if val:
                            bootloader_choice = val
                            log.info("Read bootloader choice: %s from %s", bootloader_choice, choice_path)
                            break
                except Exception as e:
                    log.warning("Could not read %s: %s", choice_path, e)

        desktop_profile = "minimal"
        for choice_path in ["/tmp/anaconda_desktop_profile", "/run/anaconda/desktop_profile"]:
            if os.path.exists(choice_path):
                try:
                    with open(choice_path, "r", encoding="utf-8") as f:
                        value = f.read().strip()
                        if value in ("minimal", "full"):
                            desktop_profile = value
                            break
                except Exception as e:
                    log.warning("Could not read %s: %s", choice_path, e)

        remove_solarui = "no"
        for choice_path in ["/tmp/anaconda_remove_solarui", "/run/anaconda/remove_solarui"]:
            if os.path.exists(choice_path):
                try:
                    with open(choice_path, "r", encoding="utf-8") as f:
                        value = f.read().strip()
                        if value in ("yes", "no"):
                            remove_solarui = value
                            break
                except Exception as e:
                    log.warning("Could not read %s: %s", choice_path, e)

        usage_profile = "standard"
        for choice_path in ["/tmp/anaconda_usage_profile", "/run/anaconda/usage_profile"]:
            if os.path.exists(choice_path):
                try:
                    with open(choice_path, "r", encoding="utf-8") as f:
                        value = f.read().strip()
                        if value in ("light", "daily", "office", "gaming", "standard", "developer"):
                            usage_profile = value
                            break
                except Exception as e:
                    log.warning("Could not read %s: %s", choice_path, e)

        # 3. Persist choices to target sysroot
        try:
            with open(join_paths(self._sysroot, "etc/blazeos-desktop-choice"), "w", encoding="utf-8") as f:
                f.write(desktop_choice + "\n")
            with open(join_paths(self._sysroot, "etc/blazeos-bootloader-choice"), "w", encoding="utf-8") as f:
                f.write(bootloader_choice + "\n")
            with open(join_paths(self._sysroot, "etc/blazeos-desktop-profile"), "w", encoding="utf-8") as f:
                f.write(desktop_profile + "\n")
            with open(join_paths(self._sysroot, "etc/blazeos-remove-solarui"), "w", encoding="utf-8") as f:
                f.write(remove_solarui + "\n")
            with open(join_paths(self._sysroot, "etc/blazeos-usage-profile"), "w", encoding="utf-8") as f:
                f.write(usage_profile + "\n")
        except Exception as e:
            log.warning("Could not persist blazeos choices to target: %s", e)

        # Install an optional desktop while Anaconda still owns the progress UI.
        # First boot must never sit on a black console waiting for mirrors/DNF.
        if desktop_choice not in ("solarui", "solarui_pure", "niri") or usage_profile != "standard":
            state_dir = join_paths(self._sysroot, "var/lib/blazeos")
            os.makedirs(state_dir, exist_ok=True)
            pending = join_paths(state_dir, "desktop-provision-pending")
            try:
                with open(pending, "w", encoding="utf-8") as f:
                    f.write("desktop={}\nprofile={}\nusage_profile={}\nremove_solarui={}\n".format(
                        desktop_choice, desktop_profile, usage_profile, remove_solarui))
                command = [
                    "chroot", self._sysroot, "/usr/bin/env", "BLAZEOS_FORCE_PROVISION=1",
                    "/usr/local/bin/blazeos-desktop-provision"
                ]
                log.info("Provisioning selected desktop during installation: %s", command)
                result = subprocess.run(command, timeout=3300, check=False,
                                        stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
                                        text=True)
                log.info("Desktop provisioning exited %s:\n%s", result.returncode, result.stdout[-12000:])
                if result.returncode != 0:
                    log.warning("Desktop provisioning will retry after graphical login")
            except (OSError, subprocess.SubprocessError) as e:
                log.warning("Desktop provisioning could not run in target; queued retry: %s", e)

        # 4. Purge liveuser from target sysroot
        self._purge_liveuser()

        # 5. Configure AccountsService and desktop groups for all created normal users (UID >= 1000)
        self._configure_users(desktop_choice)

        # 6. Configure GDM custom.conf
        self._configure_gdm(desktop_choice)

        # 7. Configure Wayland sessions
        self._configure_sessions(desktop_choice)

        # 8. Apply bootloader choice
        if bootloader_choice == "limine":
            self._apply_limine()

        # 9. Enable optimization and postinstall services on target sysroot
        self._enable_services()

        log.info("=== BlazeFinalizeInstallationTask completed successfully ===")

    def _purge_liveuser(self):
        log.info("Purging any residual liveuser accounts from target sysroot...")
        passwd_path = join_paths(self._sysroot, "etc/passwd")
        if os.path.exists(passwd_path):
            try:
                with open(passwd_path, "r", encoding="utf-8") as f:
                    lines = [l for l in f if not l.startswith("liveuser:")]
                with open(passwd_path, "w", encoding="utf-8") as f:
                    f.writelines(lines)
            except Exception as e:
                log.warning("Failed to clean liveuser from target passwd: %s", e)

        shadow_path = join_paths(self._sysroot, "etc/shadow")
        if os.path.exists(shadow_path):
            try:
                with open(shadow_path, "r", encoding="utf-8") as f:
                    lines = [l for l in f if not l.startswith("liveuser:")]
                with open(shadow_path, "w", encoding="utf-8") as f:
                    f.writelines(lines)
            except Exception as e:
                log.warning("Failed to clean liveuser from target shadow: %s", e)

        group_path = join_paths(self._sysroot, "etc/group")
        if os.path.exists(group_path):
            try:
                new_lines = []
                with open(group_path, "r", encoding="utf-8") as f:
                    for line in f:
                        if line.startswith("liveuser:"):
                            continue
                        parts = line.strip().split(":")
                        if len(parts) == 4:
                            members = [m for m in parts[3].split(",") if m and m != "liveuser"]
                            parts[3] = ",".join(members)
                            new_lines.append(":".join(parts) + "\n")
                        else:
                            new_lines.append(line)
                with open(group_path, "w", encoding="utf-8") as f:
                    f.writelines(new_lines)
            except Exception as e:
                log.warning("Failed to clean liveuser from target group: %s", e)

        gshadow_path = join_paths(self._sysroot, "etc/gshadow")
        if os.path.exists(gshadow_path):
            try:
                new_lines = []
                with open(gshadow_path, "r", encoding="utf-8") as f:
                    for line in f:
                        if line.startswith("liveuser:"):
                            continue
                        parts = line.strip().split(":")
                        if len(parts) == 4:
                            members = [m for m in parts[3].split(",") if m and m != "liveuser"]
                            parts[3] = ",".join(members)
                            new_lines.append(":".join(parts) + "\n")
                        else:
                            new_lines.append(line)
                with open(gshadow_path, "w", encoding="utf-8") as f:
                    f.writelines(new_lines)
            except Exception as e:
                log.warning("Failed to clean liveuser from target gshadow: %s", e)

        for p in [
            join_paths(self._sysroot, "home/liveuser"),
            join_paths(self._sysroot, "var/lib/AccountsService/users/liveuser"),
            join_paths(self._sysroot, "etc/sudoers.d/liveuser"),
        ]:
            if os.path.exists(p):
                try:
                    if os.path.isdir(p):
                        shutil.rmtree(p, ignore_errors=True)
                    else:
                        os.remove(p)
                except Exception:
                    pass

    def _configure_users(self, desktop_choice="solarui"):
        log.info("Configuring users in AccountsService with desktop choice: %s", desktop_choice)
        users_dir = join_paths(self._sysroot, "var/lib/AccountsService/users")
        make_directories(users_dir)

        passwd_path = join_paths(self._sysroot, "etc/passwd")
        if not os.path.exists(passwd_path):
            return

        session_info = BLAZE_SESSION_MAP.get(desktop_choice, ("solarui", "wayland", "solarui.desktop"))
        session_name, session_type, _ = session_info

        desktop_groups = ["wheel", "video", "audio", "input", "render"]

        try:
            with open(passwd_path, "r", encoding="utf-8") as f:
                for line in f:
                    parts = line.strip().split(":")
                    if len(parts) >= 6:
                        username = parts[0]
                        try:
                            uid = int(parts[2])
                        except ValueError:
                            continue
                        home_dir = parts[5]

                        if 1000 <= uid < 65534 and username != "liveuser":
                            log.info("Configuring target user: %s (UID: %d, Session: %s)", username, uid, session_name)
                            
                            user_file = join_paths(users_dir, username)
                            content = (
                                "[User]\n"
                                f"Session={session_name}\n"
                                f"SessionType={session_type}\n"
                                "Icon=/usr/share/icons/hicolor/256x256/apps/solarui.png\n"
                            )
                            with open(user_file, "w", encoding="utf-8") as uf:
                                uf.write(content)
                            os.chmod(user_file, 0o600)

                            self._add_user_to_groups(username, desktop_groups)

                            target_home = join_paths(self._sysroot, home_dir.lstrip("/"))
                            if os.path.isdir(target_home):
                                # -- Noctalia config
                                noctalia_dir = join_paths(target_home, ".config/noctalia")
                                make_directories(noctalia_dir)
                                skel_noctalia = join_paths(self._sysroot, "etc/skel/.config/noctalia/settings.toml")
                                user_noctalia = join_paths(noctalia_dir, "settings.toml")
                                if os.path.exists(skel_noctalia) and not os.path.exists(user_noctalia):
                                    shutil.copy2(skel_noctalia, user_noctalia)
                                    try:
                                        os.chown(user_noctalia, uid, uid)
                                    except Exception:
                                        pass

                                # -- SolarUI / Niri config
                                solarui_dir = join_paths(target_home, ".config/solarui")
                                make_directories(solarui_dir)
                                niri_cfg = join_paths(self._sysroot, "etc/solarui/niri.kdl")
                                user_niri = join_paths(solarui_dir, "niri.kdl")
                                if os.path.exists(niri_cfg) and not os.path.exists(user_niri):
                                    shutil.copy2(niri_cfg, user_niri)
                                    try:
                                        os.chown(user_niri, uid, uid)
                                    except Exception:
                                        pass

                                # -- Caelestia shell config (fixes grey screen crash)
                                skel_caelestia = join_paths(self._sysroot, "etc/skel/.config/caelestia")
                                user_caelestia = join_paths(target_home, ".config/caelestia")
                                if os.path.isdir(skel_caelestia) and not os.path.isdir(user_caelestia):
                                    shutil.copytree(skel_caelestia, user_caelestia)
                                    try:
                                        for root_d, dirs, files in os.walk(user_caelestia):
                                            os.chown(root_d, uid, uid)
                                            for ff in files:
                                                os.chown(os.path.join(root_d, ff), uid, uid)
                                    except Exception:
                                        pass

                                # -- Quickshell / Caelestia QML config (fixes grey screen crash)
                                skel_qs = join_paths(self._sysroot, "etc/skel/.config/quickshell")
                                user_qs = join_paths(target_home, ".config/quickshell")
                                if os.path.isdir(skel_qs) and not os.path.isdir(user_qs):
                                    shutil.copytree(skel_qs, user_qs)
                                    try:
                                        for root_d, dirs, files in os.walk(user_qs):
                                            os.chown(root_d, uid, uid)
                                            for ff in files:
                                                os.chown(os.path.join(root_d, ff), uid, uid)
                                    except Exception:
                                        pass
        except Exception as e:
            log.warning("Failed during _configure_users: %s", e)

    def _add_user_to_groups(self, username, groups):
        group_path = join_paths(self._sysroot, "etc/group")
        if not os.path.exists(group_path):
            return
        try:
            lines = []
            with open(group_path, "r", encoding="utf-8") as f:
                for line in f:
                    parts = line.strip().split(":")
                    if len(parts) == 4 and parts[0] in groups:
                        members = [m for m in parts[3].split(",") if m]
                        if username not in members:
                            members.append(username)
                        parts[3] = ",".join(members)
                        lines.append(":".join(parts) + "\n")
                    else:
                        lines.append(line)
            with open(group_path, "w", encoding="utf-8") as f:
                f.writelines(lines)
        except Exception as e:
            log.warning("Failed to add user %s to groups: %s", username, e)

    def _configure_gdm(self, desktop_choice="solarui"):
        gdm_conf = join_paths(self._sysroot, "etc/gdm/custom.conf")
        make_directories(os.path.dirname(gdm_conf))
        session_info = BLAZE_SESSION_MAP.get(desktop_choice, ("solarui", "wayland", "solarui.desktop"))
        default_session = session_info[2]
        content = (
            "# GDM configuration storage\n"
            "[daemon]\n"
            "WaylandEnable=true\n"
            f"DefaultSession={default_session}\n"
            "InitialSetupEnable=false\n"
            "\n"
            "[security]\n"
            "\n"
            "[debug]\n"
        )
        try:
            with open(gdm_conf, "w", encoding="utf-8") as f:
                f.write(content)
            log.info("Set GDM custom.conf DefaultSession=%s on target sysroot.", default_session)
        except Exception as e:
            log.warning("Failed to write %s: %s", gdm_conf, e)

    def _configure_sessions(self, desktop_choice):
        sessions_dir = join_paths(self._sysroot, "usr/share/wayland-sessions")
        if not os.path.isdir(sessions_dir):
            return

        self._set_desktop_nodisplay(join_paths(sessions_dir, "gnome-classic.desktop"), True)

        if desktop_choice in ["solarui", "solarui_pure"]:
            log.info("Pure SolarUI mode: hiding gnome.desktop and niri.desktop")
            self._set_desktop_nodisplay(join_paths(sessions_dir, "niri.desktop"), True)
            self._set_desktop_nodisplay(join_paths(sessions_dir, "gnome.desktop"), True)
            self._set_desktop_nodisplay(join_paths(sessions_dir, "solarui.desktop"), False)
        elif desktop_choice == "niri":
            log.info("Niri mode: enabling niri.desktop")
            self._set_desktop_nodisplay(join_paths(sessions_dir, "niri.desktop"), False)
            self._set_desktop_nodisplay(join_paths(sessions_dir, "gnome.desktop"), True)
            self._set_desktop_nodisplay(join_paths(sessions_dir, "solarui.desktop"), False)
        elif desktop_choice == "gnome":
            log.info("GNOME mode: enabling gnome.desktop")
            self._set_desktop_nodisplay(join_paths(sessions_dir, "niri.desktop"), True)
            self._set_desktop_nodisplay(join_paths(sessions_dir, "gnome.desktop"), False)
            self._set_desktop_nodisplay(join_paths(sessions_dir, "solarui.desktop"), False)
        else:
            log.info("Multi-desktop mode (%s): keeping standard sessions visible", desktop_choice)
            self._set_desktop_nodisplay(join_paths(sessions_dir, "solarui.desktop"), False)
            self._set_desktop_nodisplay(join_paths(sessions_dir, "gnome.desktop"), False)

    def _set_desktop_nodisplay(self, filepath, hide):
        if not os.path.exists(filepath):
            return
        try:
            with open(filepath, "r", encoding="utf-8") as f:
                lines = f.readlines()
            new_lines = []
            found = False
            for line in lines:
                if line.strip().startswith("NoDisplay="):
                    new_lines.append(f"NoDisplay={'true' if hide else 'false'}\n")
                    found = True
                else:
                    new_lines.append(line)
            if not found:
                final_lines = []
                for line in new_lines:
                    final_lines.append(line)
                    if line.strip() == "[Desktop Entry]":
                        final_lines.append(f"NoDisplay={'true' if hide else 'false'}\n")
                new_lines = final_lines
            with open(filepath, "w", encoding="utf-8") as f:
                f.writelines(new_lines)
        except Exception as e:
            log.warning("Failed to update NoDisplay in %s: %s", filepath, e)

    def _apply_limine(self):
        log.info("Applying Limine bootloader to sysroot: %s", self._sysroot)
        script_path = join_paths(self._sysroot, "usr/local/bin/blaze-bootloader")
        if not os.path.exists(script_path):
            script_path = "/usr/local/bin/blaze-bootloader"

        if os.path.exists(script_path):
            try:
                cmd = [script_path, "switch-to-limine", f"--sysroot={self._sysroot}"]
                log.info("Executing: %s", " ".join(cmd))
                res = subprocess.run(cmd, capture_output=True, text=True)
                log.info("blaze-bootloader returncode: %d\nstdout: %s\nstderr: %s", res.returncode, res.stdout, res.stderr)
            except Exception as e:
                log.warning("Failed to run blaze-bootloader: %s", e)
        else:
            log.warning("blaze-bootloader script not found at %s", script_path)

    def _enable_services(self):
        wants_dir = join_paths(self._sysroot, "etc/systemd/system/multi-user.target.wants")
        make_directories(wants_dir)
        for svc in ["blaze-optimization.service", "blazeos-postinstall.service"]:
            svc_target = join_paths(wants_dir, svc)
            if not os.path.exists(svc_target):
                try:
                    os.symlink(f"/etc/systemd/system/{svc}", svc_target)
                    log.info("Enabled %s in target multi-user.target.wants", svc)
                except OSError as e:
                    log.warning("Could not symlink %s: %s", svc, e)


class SetContextsTask(InstallationTask):
    """Task to set file contexts on target system.

    We need to handle SELinux relabeling for a few reasons:

    - %post scripts that write files into places in /etc, but don't do labeling correctly
    - Anaconda code that does the same (e.g. moving our log files into /var/log/anaconda)
    - ostree payloads, where all of the labeling of /var is the installer's responsibility
      (see https://github.com/ostreedev/ostree/pull/872 )
    - OSTree variants of the traditional mounts if present
    """
    def __init__(self, sysroot):
        """Create a new task.

        :param sysroot: a path to the root of installed system
        :type sysroot: str
        """
        super().__init__()
        self._sysroot = sysroot

    @property
    def name(self):
        return "Set file contexts"

    def run(self):
        """Relabel files (set contexts).

        Do not fail if the executable is not present.
        """
        dirs_to_relabel = [
            "/boot",
            "/dev",
            "/etc",
            "/lib64",
            "/root",
            "/usr/lib",
            "/usr/lib64",
            "/var/cache/yum",
            "/var/home",
            "/var/lib",
            "/var/lock",
            "/var/log",
            "/var/media",
            "/var/mnt",
            "/var/opt",
            "/var/roothome",
            "/var/run",
            "/var/spool",
            "/var/srv"
        ]

        log.info("Restoring SELinux contexts.")
        if not restorecon(dirs_to_relabel, root=self._sysroot, skip_nonexistent=True):
            log.warning("Cannot restore contexts because restorecon was not installed.")


# Module-private helper for RunInstallationTask.
class _RemoteErrorUI:
    """Error UI proxy that forwards dialog calls to the real UI over D-Bus.

    This is used in the Boss process where errorHandler.ui is not set.
    It forwards showYesNoQuestion, showDetailedError, and showError
    calls via the RunInstallationTask's error_raised_signal, blocking
    until the UI responds via respond_to_error.
    """

    def __init__(self, task):
        self._task = task

    def showYesNoQuestion(self, message):
        return self._task._show_dialog(message, InstallationErrorDialogType.YES_NO)

    def showDetailedError(self, message, details, buttons=None):
        full_message = message
        if details:
            full_message += "\n\n" + details
        self._task._show_dialog(full_message, InstallationErrorDialogType.FATAL_ERROR)
        return False

    def showError(self, message):
        self._task._show_dialog(message, InstallationErrorDialogType.FATAL_ERROR)


class RunInstallationTask(InstallationTask):
    """Task to run the installation queue."""

    def __init__(self, install_manager):
        """Create a new task.
        """
        super().__init__()
        self._total_steps = 0
        self._install_manager = install_manager
        self._error_raised_signal = Signal()
        self._error_response_event = Event()
        self._error_response_signal = Signal()
        self._error_should_continue = False
        self._fatal_error_already_emitted = False

    @property
    def error_raised_signal(self):
        """Signal emitted when an error needs user interaction.

        Carries the error message string and InstallationErrorDialogType value.
        """
        return self._error_raised_signal

    @property
    def error_response_signal(self):
        """Signal emitted when the user responds to a pending error.

        Carries a boolean: True to continue, False to abort.
        """
        return self._error_response_signal

    def _show_dialog(self, message, dialog_type):
        """Emit error signal and block until UI responds.

        :param message: the error message to display
        :param dialog_type: the type of dialog to show
        """
        if dialog_type == InstallationErrorDialogType.FATAL_ERROR:
            self._fatal_error_already_emitted = True
        self._error_response_event.clear()
        self._error_raised_signal.emit(message, dialog_type)
        self._error_response_event.wait()
        return self._error_should_continue

    def respond_to_error(self, should_continue):
        """Respond to a previously reported error.

        :param should_continue: True to continue, False to abort.
        """
        self._error_should_continue = should_continue
        self._error_response_event.set()
        self._error_response_signal.emit(should_continue)

    def _thread_failed_callback(self, *exc_info):
        """Emit the fatal error before reporting the failure.

        Skips emission if a fatal error was already emitted by _show_dialog
        to avoid overwriting the original error message (e.g. ScriptError
        emits via _show_dialog, then sys.exit triggers this callback with
        a less informative SystemExit message).
        """
        if not self._fatal_error_already_emitted:
            self._error_raised_signal.emit(
                str(exc_info[1]), InstallationErrorDialogType.FATAL_ERROR
            )
        super()._thread_failed_callback(*exc_info)

    @property
    def name(self):
        """Name of the task"""
        return "Run the installation queue."

    @property
    def steps(self):
        """Total number of steps."""
        return self._total_steps

    def run(self):
        """Run the task."""
        self._run_installation()

    def for_publication(self):
        """Return a DBus representation."""
        return CategoryReportTaskInterface(self)

    def _queue_started_cb(self, task):
        """The installation queue was started."""
        self.report_category(task.task_category)
        self.report_progress(task.status_message)

    def _task_completed_cb(self, task):
        """The installation task was completed."""
        self.report_progress("", step_size=1)

    def _progress_report_cb(self, step, message):
        """Handle a progress report of a task."""
        self.report_progress(message)

    def _prepare_configuration(self):
        """Prepare queue with tasks configuring installed system."""
        payloads_proxy = PAYLOADS.get_proxy()
        payload_path = payloads_proxy.ActivePayload
        if not payload_path:
            log.error("No active payload found! Can't continue install.")
            raise RuntimeError("No active payload")

        payload_proxy = PAYLOADS.get_proxy(payload_path)
        configuration_queue = TaskQueue("Configuration queue")

        # connect progress reporting
        configuration_queue.queue_started.connect(self._queue_started_cb)
        configuration_queue.task_completed.connect(self._task_completed_cb)

        # import certificates first
        # they may be required for subscription, initramfs regenerating, ... ?
        if is_module_available(SECURITY):
            certificates_import = TaskQueue(
                "Certificates import",
                _("Importing certificates"),
                CATEGORY_SYSTEM
            )
            certificates_proxy = SECURITY.get_proxy(CERTIFICATES)
            certificates_import.append_dbus_tasks(SECURITY, [
                certificates_proxy.InstallWithTask()
            ])
            configuration_queue.append(certificates_import)

        # schedule the execute methods of ksdata that require an installed system to be present
        os_config = TaskQueue(
            "Installed system configuration",
            _("Configuring installed system"),
            CATEGORY_SYSTEM
        )

        # add installation tasks for the Security DBus module
        if is_module_available(SECURITY):
            security_proxy = SECURITY.get_proxy()
            security_dbus_tasks = security_proxy.InstallWithTasks()
            os_config.append_dbus_tasks(SECURITY, security_dbus_tasks)

        # add installation tasks for the Timezone DBus module
        # run these tasks before tasks of the Services module
        if is_module_available(TIMEZONE):
            timezone_proxy = TIMEZONE.get_proxy()
            timezone_dbus_tasks = timezone_proxy.InstallWithTasks()
            os_config.append_dbus_tasks(TIMEZONE, timezone_dbus_tasks)

        # add installation tasks for the Services DBus module
        if is_module_available(SERVICES):
            services_proxy = SERVICES.get_proxy()
            services_dbus_tasks = services_proxy.InstallWithTasks()
            os_config.append_dbus_tasks(SERVICES, services_dbus_tasks)

        # add installation tasks for the Localization DBus module
        if is_module_available(LOCALIZATION):
            localization_proxy = LOCALIZATION.get_proxy()
            localization_dbus_tasks = localization_proxy.InstallWithTasks()
            os_config.append_dbus_tasks(LOCALIZATION, localization_dbus_tasks)

        # add the Firewall configuration task
        if conf.target.can_configure_network:
            firewall_proxy = NETWORK.get_proxy(FIREWALL)
            firewall_dbus_task = firewall_proxy.InstallWithTask()
            os_config.append_dbus_tasks(NETWORK, [firewall_dbus_task])

        configuration_queue.append(os_config)

        # schedule network configuration (if required)
        if conf.target.can_configure_network and conf.system.provides_network_config:
            overwrite = payload_proxy.Type in PAYLOAD_LIVE_TYPES
            network_config = TaskQueue(
                "Network configuration",
                _("Writing network configuration"),
                CATEGORY_SYSTEM
            )
            network_config.append(Task(
                "Network configuration",
                network.write_configuration,
                (overwrite, )
            ))
            configuration_queue.append(network_config)

        # add installation tasks for the Subscription DBus module
        if is_module_available(SUBSCRIPTION):
            # we only run the tasks if the Subscription module is available
            subscription_config = TaskQueue(
                "Subscription configuration",
                _("Configuring Red Hat subscription"),
                CATEGORY_SYSTEM
            )
            subscription_proxy = SUBSCRIPTION.get_proxy()
            subscription_dbus_tasks = subscription_proxy.InstallWithTasks()
            subscription_config.append_dbus_tasks(SUBSCRIPTION, subscription_dbus_tasks)
            configuration_queue.append(subscription_config)

        # add installation tasks for the Users DBus module
        if is_module_available(USERS):
            user_config = TaskQueue(
                "User creation",
                _("Creating users"),
                CATEGORY_SYSTEM
            )
            users_proxy = USERS.get_proxy()
            users_dbus_tasks = users_proxy.InstallWithTasks()
            user_config.append_dbus_tasks(USERS, users_dbus_tasks)
            configuration_queue.append(user_config)

        # Anaconda addon configuration
        addon_config = TaskQueue(
            "Anaconda addon configuration",
            _("Configuring addons"),
            CATEGORY_SYSTEM
        )

        tasks_list = self._install_manager.collect_install_system_tasks()
        for task_proxy in tasks_list:
            addon_config.append(DBusTask(task_proxy))

        configuration_queue.append(addon_config)

        # Initramfs generation
        generate_initramfs = TaskQueue(
            "Initramfs generation",
            _("Generating initramfs"),
            CATEGORY_BOOTLOADER
        )
        bootloader_proxy = STORAGE.get_proxy(BOOTLOADER)

        def run_generate_initramfs():
            tasks = bootloader_proxy.GenerateInitramfsWithTasks(
                payload_proxy.Type,
                payloads_proxy.GetKernelVersionList()
            )

            for task in tasks:
                sync_run_task(STORAGE.get_proxy(task))

        generate_initramfs.append(Task(
            "Generate initramfs",
            run_generate_initramfs
        ))
        configuration_queue.append(generate_initramfs)

        if is_module_available(SECURITY):
            security_proxy = SECURITY.get_proxy()

            # Configure FIPS.
            configuration_queue.append_dbus_tasks(SECURITY, [
                security_proxy.ConfigureFIPSWithTask()
            ])

            # Join a realm. This can run only after network
            # is configured in the target system chroot.
            configuration_queue.append_dbus_tasks(SECURITY, [
                security_proxy.JoinRealmWithTask()
            ])

        # Calling zipl should be the last task on s390
        configuration_queue.append_dbus_tasks(STORAGE, [
            bootloader_proxy.FixZIPLBootloaderWithTask()
        ])

        # setup kexec reboot if requested
        if flags.flags.kexec:
            kexec_setup = TaskQueue(
                "Kexec setup",
                _("Setting up kexec"),
                CATEGORY_BOOTLOADER
            )
            kexec_setup.append(Task(
                "Setup kexec",
                setup_kexec
            ))
            configuration_queue.append(kexec_setup)

        # write anaconda related configs & kickstarts
        write_configs = TaskQueue(
            "Write configs and kickstarts",
            _("Storing configuration files and kickstarts"),
            CATEGORY_SYSTEM
        )

        # Write the kickstart file to the installed system (or, copy the input
        # kickstart file over if one exists).
        if conf.target.can_save_output_kickstart:
            # write anaconda related configs & kickstarts
            write_configs.append(Task("Store kickstarts", _writeKS_via_boss))
        else:
            # don't write the kickstart file to the installed system if this has
            # been disabled by the nosave option
            log.warning("Writing of the output kickstart to installed system has been disabled"
                        " by the nosave option.")

        # only add write_configs to the main queue if we actually store some kickstarts/configs
        if write_configs.task_count:
            configuration_queue.append(write_configs)

        post_scripts = TaskQueue(
            "Post installation scripts",
            _("Running post-installation scripts"),
            CATEGORY_SYSTEM
        )
        scripts_proxy = RUNTIME.get_proxy(SCRIPTS)
        post_scripts.append_dbus_tasks(RUNTIME, [
            scripts_proxy.RunScriptsWithTask(KS_SCRIPT_POST)
        ])
        configuration_queue.append(post_scripts)

        configuration_queue.append(Task(
            "Copy installation logs",
            CopyLogsTask(conf.target.system_root).run
        ))
        configuration_queue.append(Task(
            "Finalize BlazeOS desktop and bootloader",
            BlazeFinalizeInstallationTask(conf.target.system_root).run
        ))
        configuration_queue.append(Task(
            "Set file contexts",
            SetContextsTask(conf.target.system_root).run
        ))

        return configuration_queue

    def _prepare_installation(self):
        """Prepare the installation task queue.

        This method builds and returns a queue of tasks that perform the system installation.
        The queue includes tasks for setting up the environment, configuring storage,
        installing the software payload, running installation scripts, setting up the
        bootloader, and executing post-installation steps.
        """
        payloads_proxy = PAYLOADS.get_proxy()
        payload_path = payloads_proxy.ActivePayload
        if not payload_path:
            log.error("No active payload found! Can't continue install.")
            raise RuntimeError("No active payload")

        payload_proxy = PAYLOADS.get_proxy(payload_path)
        installation_queue = TaskQueue("Installation queue")

        # connect progress reporting
        installation_queue.queue_started.connect(self._queue_started_cb)
        installation_queue.task_completed.connect(self._task_completed_cb)

        # setup the installation environment
        setup_environment = TaskQueue(
            "Installation environment setup",
            _("Setting up the installation environment"),
            CATEGORY_ENVIRONMENT
        )

        tasks_list = self._install_manager.collect_configure_runtime_tasks()
        for task_proxy in tasks_list:
            setup_environment.append(DBusTask(task_proxy))

        # Add configuration tasks for the Localization DBus module.
        if is_module_available(LOCALIZATION):
            localization_proxy = LOCALIZATION.get_proxy()
            # Populate the missing keyboard values before the payload installation,
            # so the module requirements can be generated for the right configuration.
            # FIXME: Make sure that the module always returns right values.
            populate_task = localization_proxy.PopulateMissingKeyboardConfigurationWithTask()
            setup_environment.append_dbus_tasks(LOCALIZATION, [populate_task])

        installation_queue.append(setup_environment)

        # Do partitioning.
        # Depending on current payload the storage might be apparently configured
        # either before or after package/payload installation.
        # So let's have two task queues - early storage & late storage.
        storage_proxy = STORAGE.get_proxy()
        early_storage = TaskQueue(
            "Early storage configuration",
            _("Configuring storage"),
            CATEGORY_STORAGE
        )
        early_storage.append_dbus_tasks(STORAGE, storage_proxy.InstallWithTasks())

        if payload_proxy.Type == PAYLOAD_TYPE_DNF:
            conf_task = storage_proxy.WriteConfigurationWithTask(payload_proxy.Type)
            early_storage.append_dbus_tasks(STORAGE, [conf_task])

        installation_queue.append(early_storage)

        # Run %pre-install scripts with the filesystem mounted and no packages
        pre_install_scripts = TaskQueue(
            "Pre-install scripts",
            _("Running pre-installation scripts"),
            CATEGORY_ENVIRONMENT
        )
        scripts_proxy = RUNTIME.get_proxy(SCRIPTS)
        pre_install_scripts.append_dbus_tasks(RUNTIME, [
            scripts_proxy.RunScriptsWithTask(KS_SCRIPT_PREINSTALL)
        ])
        installation_queue.append(pre_install_scripts)

        # Do various pre-installation tasks
        # - try to discover a realm (if any)
        # - check for possibly needed additional packages.
        pre_install = TaskQueue(
            "Pre install tasks",
            _("Running pre-installation tasks"),
            CATEGORY_SOFTWARE
        )

        # Make name resolution work for rpm scripts in chroot.
        # Also make sure dns resolution works in %post scripts
        # when systemd-resolved is not available.
        if conf.system.provides_resolver_config and \
                not is_service_installed("systemd-resolved.service"):
            pre_install.append(Task(
                "Copy resolv.conf to sysroot",
                network.copy_resolv_conf_to_root,
                (conf.target.system_root, )
            ))

        if is_module_available(SECURITY):
            security_proxy = SECURITY.get_proxy()

            # Discover a realm.
            pre_install.append_dbus_tasks(SECURITY, [
                security_proxy.DiscoverRealmWithTask()
            ])

            # Set up FIPS for the payload installation.
            fips_task = security_proxy.PreconfigureFIPSWithTask(payload_proxy.Type)
            pre_install.append_dbus_tasks(SECURITY, [fips_task])

            # Import certificates so they are available for rpm scripts
            certificates_proxy = SECURITY.get_proxy(CERTIFICATES)
            certificates_task = certificates_proxy.PreInstallWithTask(payload_proxy.Type)
            pre_install.append_dbus_tasks(SECURITY, [certificates_task])

        installation_queue.append(pre_install)

        payload_install = TaskQueue(
            "Payload installation",
            _("Installing the software"),
            CATEGORY_SOFTWARE
        )

        tasks = payloads_proxy.InstallWithTasks()
        payload_install.append_dbus_tasks(PAYLOADS, tasks)

        installation_queue.append(payload_install)

        # for some payloads storage is configured after the payload is installed
        if payload_proxy.Type != PAYLOAD_TYPE_DNF:
            late_storage = TaskQueue(
                "Late storage configuration",
                _("Configuring storage"),
                CATEGORY_STORAGE,
            )
            conf_task = storage_proxy.WriteConfigurationWithTask(payload_proxy.Type)
            late_storage.append_dbus_tasks(STORAGE, [conf_task])
            installation_queue.append(late_storage)

        # Do bootloader.
        bootloader_proxy = STORAGE.get_proxy(BOOTLOADER)
        bootloader_install = TaskQueue(
            "Bootloader installation",
            _("Installing boot loader"),
            CATEGORY_BOOTLOADER
        )

        def run_configure_bootloader():
            task_proxies = self._install_manager.collect_configure_bootloader_tasks(payloads_proxy.GetKernelVersionList())

            for proxy in task_proxies:
                sync_run_task(proxy)

        bootloader_install.append(Task(
            "Configure bootloader",
            run_configure_bootloader
        ))

        def run_install_bootloader():
            tasks = bootloader_proxy.InstallBootloaderWithTasks(
                payload_proxy.Type,
                payloads_proxy.GetKernelVersionList()
            )

            for task in tasks:
                sync_run_task(STORAGE.get_proxy(task))

        bootloader_install.append(Task(
            "Install bootloader",
            run_install_bootloader
        ))
        installation_queue.append(bootloader_install)

        post_install = TaskQueue(
            "Post-installation setup tasks",
            _("Performing post-installation setup tasks"),
            CATEGORY_SYSTEM
        )
        tasks = payloads_proxy.PostInstallWithTasks()
        post_install.append_dbus_tasks(PAYLOADS, tasks)
        installation_queue.append(post_install)

        # Create snapshot
        snapshot_proxy = STORAGE.get_proxy(SNAPSHOT)

        if snapshot_proxy.IsRequested(SNAPSHOT_WHEN_POST_INSTALL):
            snapshot_creation = TaskQueue(
                "Creating post installation snapshots",
                _("Creating snapshots"),
                CATEGORY_STORAGE
            )
            snapshot_task = snapshot_proxy.CreateWithTask(SNAPSHOT_WHEN_POST_INSTALL)
            snapshot_creation.append_dbus_tasks(STORAGE, [snapshot_task])
            installation_queue.append(snapshot_creation)

        return installation_queue

    def _run_installation(self):
        """Run the complete installation."""
        from pyanaconda.errors import errorHandler

        queue = TaskQueue("Complete installation queue")
        queue.append(self._prepare_installation())
        queue.append(self._prepare_configuration())

        # notify progress tracking about the number of steps
        self._total_steps = queue.task_count

        # Set the progress reporting callback of the DBus tasks.
        # FIXME: This is a temporary workaround.
        for item in queue.nested_items:
            if isinstance(item, DBusTask):
                item._progress_cb = self._progress_report_cb

        # log contents of the main task queue
        log.info(queue.summary)

        # log tasks and queues when they are started
        # - note that we are using generators to add the counter
        queue_counter = util.item_counter(queue.queue_count)
        task_started_counter = util.item_counter(queue.task_count)
        task_completed_counter = util.item_counter(queue.task_count)
        queue.queue_started.connect(
            lambda x: log.info("Queue started: %s (%s)", x.name, next(queue_counter))
        )
        queue.task_started.connect(
            lambda x: log.info("Task started: %s (%s)", x.name, next(task_started_counter))
        )
        queue.task_completed.connect(
            lambda x: log.debug("Task completed: %s (%s) (%1.1f s)", x.name,
                                next(task_completed_counter), x.elapsed_time)
        )

        # Boss has no UserInterface; during the installation queue, tasks may call
        # errorHandler.cb() for non-fatal errors. Temporarily install a D-Bus proxy
        # that forwards dialogs to the progress spoke in the UI process.
        previous_ui = errorHandler.ui
        errorHandler.ui = _RemoteErrorUI(self)
        try:
            queue.start()
        finally:
            errorHandler.ui = previous_ui

        # done
        self.report_progress(_("Complete!"), step_number=self.steps)

        # this message is automatically detected by QE tools, do not change it lightly
        log.info(
            "All tasks in the installation queue are done. "
            "Installation successfully finished."
        )
